import React from 'react';

/**
 * ReadOnlyAnnotation
 * Displays annotation bodies in a read-only format.
 * Expects `annotation` and `env` props.
 */
const ReadOnlyAnnotation = ({ annotation, env }) => {
  if (!annotation || !annotation.body || annotation.body.length === 0) {
    return <div className="r6o-readonly-empty">No annotation data.</div>;
  }

  // Split bodies by purpose
  const tagging = annotation.body.find(b => b.purpose === 'tagging');
  const comments = annotation.body.filter(b => b.purpose === 'commenting');

  const onClose = () => {
    if (env?.onClose) {
      env.onClose();
    }
  };

  return (
    <div className="r6o-readonly-annotation">
      <div className={`tagging ${tagging?.value ? ' ' + tagging.value.toLowerCase().replace(/_/g, '-') : ''}`}>
        <p className="r6o-readonly-tag">{tagging?.value.replace(/_/g, ' ').replace(/\b\w/g, char => char.toUpperCase())}</p>
      </div>

      {/* Comments */}
      {comments.length > 0 && (
        <div className="r6o-readonly-body">
          {comments.map((body, idx) => (
            <p
              key={idx}
              className="r6o-readonly-comment"
            >
              {body.value}
            </p>
          ))}
        </div>
      )}
    </div>
  );
};

export default ReadOnlyAnnotation;
